import io


def _parse_amount(raw):
    """Parse an amount string that may be quoted, use $ and thousands
    separators, or be wrapped in parentheses to indicate a negative value."""
    text = raw.strip()
    if not text:
        return None
    negative = False
    if text.startswith("(") and text.endswith(")"):
        negative = True
        text = text[1:-1].strip()
    text = text.replace("$", "").replace(",", "").strip()
    if not text:
        return None
    value = float(text)
    return -value if negative else value


def summarize_expenses(csv_text):
    """Total the amount column per category.

    Returns {category: total} with each total rounded to 2 decimals.
    Category keys are lowercase with surrounding whitespace stripped.
    Amounts may be quoted and may use $ and thousands separators.
    An amount wrapped in parentheses is negative, accounting style.
    Rows with a missing or empty amount are skipped, as are blank lines.
    """
    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    for row in reader:
        if not row or all(not cell.strip() for cell in row):
            continue
        if len(row) < 3:
            continue
        amount = _parse_amount(row[2])
        if amount is None:
            continue
        category = row[1].strip().lower()
